def find_adj(positions, test_arr, mask_vals, connectivity=8, in_rows=None):
    result = set(positions.copy())
    masked = []
    for pos in positions:
        r, c = pos[0], pos[1]
        if 0 <= r < len(test_arr) and 0 <= c < len(test_arr[0]) and test_arr[r, c] == mask_vals:
            if in_rows and r not in in_rows:
                continue
            masked.append(pos)

    for pos in masked:
        r, c = pos[0], pos[1]
        if connectivity == 8:
            neighbors = [(r+dr, c+dc) for dr in range(-1, 2) for dc in range(-1, 2) if dr == 0 or dc == 0]
        else:
            neighbors = [(r+dr, c+dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]]

        for nr, nc in neighbors:
            if 0 <= nr < len(test_arr) and 0 <= nc < len(test_arr[0]):
                if in_rows and nr not in in_rows:
                    continue
                if test_arr[nr, nc] == mask_vals:
                    result.add((nr, nc))
    return result

